<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워 건축 설계 과정</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            height: 100vh;
        }
        #container {
            display: flex;
            flex: 1;
        }
        #sidebar, #main {
            padding: 10px;
        }
        #sidebar {
            width: 25%;
            background-color: #f4f4f4;
            overflow-y: auto;
        }
        #main {
            width: 75%;
            display: flex;
            flex-direction: column;
        }
        #drawings, #models {
            display: flex;
            flex: 1;
        }
        #drawings {
            flex-direction: column;
        }
        #models {
            flex-direction: row;
        }
        #drawings canvas, #models canvas {
            border: 1px solid #ccc;
        }
        .drawing {
            width: 100%;
            height: 100%;
        }
        .model {
            width: 50%;
            height: 100%;
        }
       .control {
            display: flex;
            justify-content: space-around;
            margin-top: 10px;
        }
        .control button {
            padding: 5px 10px;
            font-size: 12px;
        }
    </style>
</head>
<body>
    <div id="container">
        <div id="sidebar">
            <h2>롯데월드타워 건축 설계 과정</h2>
            <h3>설계도면</h3>
            <canvas id="layout" class="drawing"></canvas>
            <canvas id="level" class="drawing"></canvas>
            <canvas id="elevation" class="drawing"></canvas>
            <canvas id="section" class="drawing"></canvas>
            <h3>설계 단계별 3D 모델</h3>
            <canvas id="stage1" class="model"></canvas>
            <canvas id="stage2" class="model"></canvas>
            <canvas id="stage3" class="model"></canvas>
            <h3>완성된 3D 모델</h3>
            <canvas id="final" class="model"></canvas>
        </div>
        <div id="main">
            <div id="drawings">
                <canvas id="drawing1" class="drawing"></canvas>
                <canvas id="drawing2" class="drawing"></canvas>
                <canvas id="drawing3" class="drawing"></canvas>
                <canvas id="drawing4" class="drawing"></canvas>
            </div>
            <div id="models">
                <canvas id="model1" class="model"></canvas>
                <canvas id="model2" class="model"></canvas>
                <canvas id="model3" class="model"></canvas>
                <canvas id="model4" class="model"></canvas>
            </div>
            <div class="control">
                <button onclick="rotateModel(1)">회전</button>
                <button onclick="zoomModel(1)">확대/축소</button>
                <button onclick="resetModel(1)">초기화</button>
            </div>
        </div>
    </div>

    <script src="../runtime/three-runtime.js"></script>
    <script>
        const canvasElements = [
            { id: 'layout', width: 400, height: 300 },
            { id: 'level', width: 400, height: 300 },
            { id: 'elevation', width: 400, height: 600 },
            { id:'section', width: 400, height: 300 },
            { id: 'drawing1', width: 400, height: 300 },
            { id: 'drawing2', width: 400, height: 300 },
            { id: 'drawing3', width: 400, height: 300 },
            { id: 'drawing4', width: 400, height: 300 },
            { id:'model1', width: 400, height: 400 },
            { id:'model2', width: 400, height: 400 },
            { id:'model3', width: 400, height: 400 },
            { id:'model4', width: 400, height: 400 },
            { id: 'final', width: 400, height: 400 },
            { id: 'stage1', width: 400, height: 400 },
            { id:'stage2', width: 400, height: 400 },
            { id:'stage3', width: 400, height: 400 },
        ];

        canvasElements.forEach(element => {
            const canvas = document.getElementById(element.id);
            const context = canvas.getContext('2d');
            context.canvas.width = element.width;
            context.canvas.height = element.height;
        });

        // 3D 모델 생성 및 조작 함수
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('model1') });
        renderer.setSize(400, 400);

        const controls = new THREE.OrbitControls(camera, renderer.domElement);

        camera.position.z = 5;

        const geometry = new THREE.BoxGeometry();
        const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
        const cube = new THREE.Mesh(geometry, material);
        scene.add(cube);

        function rotateModel(modelIndex) {
            const modelCanvas = document.getElementById(`model${modelIndex}`);
            const renderer = new THREE.WebGLRenderer({ canvas: modelCanvas });
            renderer.setSize(400, 400);
            controls = new THREE.OrbitControls(camera, renderer.domElement);
            cube.rotation.y += 0.1;
            animate();
        }

        function zoomModel(modelIndex) {
            const modelCanvas = document.getElementById(`model${modelIndex}`);
            const renderer = new THREE.WebGLRenderer({ canvas: modelCanvas });
            renderer.setSize(400, 400);
            controls = new THREE.OrbitControls(camera, renderer.domElement);
            camera.position.z += 0.5;
            animate();
        }

        function resetModel(modelIndex) {
            const modelCanvas = document.getElementById(`model${modelIndex}`);
            const renderer = new THREE.WebGLRenderer({ canvas: modelCanvas });
            renderer.setSize(400, 400);
            controls = new THREE.OrbitControls(camera, renderer.domElement);
            camera.position.set(0, 0, 5);
            cube.rotation.y = 0;
            animate();
        }

        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        animate();
    </script>
</body>
</html>
